/**
 * MCP Server Generator
 * Generates a complete, standalone MCP server package for any discovered design system.
 * The generated server embeds all component data and provides rich tools for AI agents.
 */
export function generateMcpServer(ds, opts = {}) {
    const { includePreviewTool = true } = opts;
    return {
        serverCode: buildServerCode(ds, includePreviewTool),
        packageJson: buildPackageJson(ds),
        tsconfigJson: TSCONFIG_CONTENT,
        readmeContent: buildReadme(ds),
    };
}
function buildServerCode(ds, includePreviewTool) {
    const serverSlug = ds.organizationName.toLowerCase().replace(/\s+/g, '-');
    const componentDataJson = JSON.stringify(ds.components, null, 2);
    const metadataJson = JSON.stringify({
        url: ds.url,
        organizationName: ds.organizationName,
        categories: ds.categories,
        totalComponents: ds.totalComponents,
        totalStories: ds.totalStories,
        fetchedAt: ds.fetchedAt,
    }, null, 2);
    const categoriesList = ds.categories
        .slice(0, 6)
        .map(c => `"${c}"`)
        .join(', ')
        .concat(ds.categories.length > 6 ? ', ...' : '');
    const previewImport = includePreviewTool
        ? `import { createUIResource } from '@mcp-ui/server';`
        : '';
    const previewTool = includePreviewTool
        ? buildPreviewToolCode(ds)
        : '';
    return `#!/usr/bin/env node
/**
 * ${ds.organizationName} Design System MCP Server
 *
 * Auto-generated by MCP Glue Code Generator
 * Source Storybook: ${ds.url}
 * Generated: ${new Date().toISOString()}
 *
 * Stats: ${ds.totalComponents} components · ${ds.totalStories} stories · ${ds.categories.length} categories
 *
 * Add to Claude Desktop (claude_desktop_config.json):
 * {
 *   "mcpServers": {
 *     "${serverSlug}-design-system": {
 *       "command": "node",
 *       "args": ["/path/to/build/index.js"]
 *     }
 *   }
 * }
 */

import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
${previewImport}
import { z } from 'zod';

// ===== EMBEDDED DESIGN SYSTEM DATA =====
// This data was fetched from ${ds.url} on ${ds.fetchedAt}
// Re-run the generator to refresh component data.

const METADATA = ${metadataJson};

type ComponentStory = { id: string; name: string };
type Component = {
  id: string;
  name: string;
  category: string;
  fullTitle: string;
  stories: ComponentStory[];
  tags?: string[];
};

const COMPONENTS: Component[] = ${componentDataJson};

const STORYBOOK_URL = '${ds.url}';
// ========================================

function scoreComponent(c: Component, keywords: string[]): number {
  const text = \`\${c.name} \${c.fullTitle} \${c.category} \${(c.tags ?? []).join(' ')} \${c.stories.map(s => s.name).join(' ')}\`.toLowerCase();
  return keywords.reduce((score, kw) => score + (text.includes(kw) ? (kw.length > 4 ? 3 : 1) : 0), 0);
}

async function main() {
  const server = new McpServer({
    name: '${serverSlug}-design-system',
    version: '1.0.0',
  });

  // ─── Tool: list_components ───────────────────────────────────────────────
  server.tool(
    'list_components',
    \`List ${ds.organizationName} design system components. Available categories: ${categoriesList}\`,
    {
      category: z.string().optional().describe(
        \`Filter by category. Options: ${categoriesList}\`
      ),
      limit: z.number().min(1).max(200).optional().describe('Max results (default 50)'),
    },
    async ({ category, limit = 50 }) => {
      let list = COMPONENTS;
      if (category) {
        list = list.filter(c => c.category.toLowerCase().includes(category.toLowerCase()));
      }
      const shown = list.slice(0, limit);

      const rows = shown.map(c => {
        const storyNames = c.stories.map(s => s.name).join(', ');
        const tags = c.tags?.length ? \` [\${c.tags?.join(', ')}]\` : '';
        return \`- **\${c.name}**\${tags} [\${c.category}] — \${c.stories.length} stories: \${storyNames}\`;
      });

      return {
        content: [{
          type: 'text' as const,
          text: [
            \`# \${METADATA.organizationName} Components\`,
            \`Showing \${shown.length} of \${list.length} components\${category ? \` in "\${category}"\` : ''}\`,
            '',
            rows.join('\\n'),
            list.length > shown.length
              ? \`\\n...and \${list.length - shown.length} more (increase limit or filter by category)\`
              : '',
          ].join('\\n'),
        }],
      };
    }
  );

  // ─── Tool: search_components ─────────────────────────────────────────────
  server.tool(
    'search_components',
    \`Search \${METADATA.organizationName} design system components by name, purpose, category, or tags.\`,
    {
      query: z.string().describe('Search query — e.g. "button", "modal", "form input", "navigation"'),
    },
    async ({ query }) => {
      const keywords = query.toLowerCase().split(/\\s+/).filter(k => k.length > 1);
      const results = COMPONENTS
        .map(c => ({ c, score: scoreComponent(c, keywords) }))
        .filter(({ score }) => score > 0)
        .sort((a, b) => b.score - a.score)
        .slice(0, 10)
        .map(({ c }) => c);

      if (results.length === 0) {
        return {
          content: [{
            type: 'text' as const,
            text: \`No components found for "\${query}".\\n\\nAvailable categories: \${METADATA.categories.join(', ')}\`,
          }],
        };
      }

      const blocks = results.map(c => {
        const firstStory = c.stories[0];
        return [
          \`### \${c.name}\`,
          \`- **Category**: \${c.category}\`,
          \`- **Stories (\${c.stories.length})**: \${c.stories.map(s => s.name).join(', ')}\`,
          firstStory ? \`- **Story ID for preview**: \\\`\${firstStory.id}\\\`\` : '',
          c.tags?.length ? \`- **Tags**: \${c.tags.join(', ')}\` : '',
          \`- **Storybook**: \${STORYBOOK_URL}/?path=/story/\${firstStory?.id ?? ''}\`,
        ].filter(Boolean).join('\\n');
      });

      return {
        content: [{
          type: 'text' as const,
          text: \`# Search: "\${query}" — \${results.length} result(s)\\n\\n\` + blocks.join('\\n\\n'),
        }],
      };
    }
  );

  // ─── Tool: get_component ─────────────────────────────────────────────────
  server.tool(
    'get_component',
    \`Get full details for a specific \${METADATA.organizationName} component including all story variants and links.\`,
    {
      name_or_id: z.string().describe(
        'Component name (e.g. "Button", "Modal") or ID (e.g. "components--button")'
      ),
    },
    async ({ name_or_id }) => {
      const q = name_or_id.toLowerCase().trim();
      const component = COMPONENTS.find(c =>
        c.name.toLowerCase() === q ||
        c.id === q ||
        c.name.toLowerCase().includes(q) ||
        c.id.includes(q)
      );

      if (!component) {
        const suggestions = COMPONENTS
          .filter(c => scoreComponent(c, [q]) > 0)
          .slice(0, 5)
          .map(c => \`\${c.name} [\${c.category}]\`);
        return {
          content: [{
            type: 'text' as const,
            text: \`Component "\${name_or_id}" not found.\${suggestions.length ? \`\\n\\nDid you mean: \${suggestions.join(', ')}?\` : ''}\`,
          }],
          isError: true,
        };
      }

      const storiesTable = component.stories
        .map(s =>
          \`| \${s.name} | \\\`\${s.id}\\\` | [View](\${STORYBOOK_URL}/?path=/story/\${s.id}) |\`
        )
        .join('\\n');

      return {
        content: [{
          type: 'text' as const,
          text: [
            \`# \${component.name}\`,
            \`**Category**: \${component.category}\`,
            \`**Full Path**: \${component.fullTitle}\`,
            component.tags?.length ? \`**Tags**: \${component.tags.join(', ')}\` : '',
            \`**Storybook Docs**: \${STORYBOOK_URL}/?path=/docs/\${component.id}\`,
            '',
            \`## Stories (\${component.stories.length})\`,
            '',
            '| Story | ID | Link |',
            '|-------|-----|------|',
            storiesTable,
            '',
            '## Usage',
            \`Use story ID with \\\`preview_component\\\` to see a live preview.\`,
            \`First story ID: \\\`\${component.stories[0]?.id ?? 'N/A'}\\\`\`,
          ].filter(l => l !== null).join('\\n'),
        }],
      };
    }
  );

  // ─── Tool: suggest_component ─────────────────────────────────────────────
  server.tool(
    'suggest_component',
    \`Suggest the best \${METADATA.organizationName} components for a UI use case. Describe what you need and get ranked recommendations.\`,
    {
      description: z.string().describe(
        'Describe the UI you want to build, e.g. "a button to submit a form", "show a list of users with avatars", "navigation sidebar"'
      ),
    },
    async ({ description }) => {
      const keywords = description.toLowerCase().split(/[\\s,]+/).filter(k => k.length > 2);
      const ranked = COMPONENTS
        .map(c => ({ c, score: scoreComponent(c, keywords) }))
        .filter(({ score }) => score > 0)
        .sort((a, b) => b.score - a.score)
        .slice(0, 5);

      if (ranked.length === 0) {
        return {
          content: [{
            type: 'text' as const,
            text: \`No specific suggestions for "\${description}".\\nBrowse all \${COMPONENTS.length} components with \\\`list_components\\\` or \\\`search_components\\\`.\`,
          }],
        };
      }

      const blocks = ranked.map(({ c }, i) => {
        const firstStory = c.stories[0];
        return [
          \`### \${i + 1}. \${c.name}\`,
          \`- **Category**: \${c.category}\`,
          \`- **Variants**: \${c.stories.map(s => s.name).join(', ')}\`,
          firstStory ? \`- **Live preview**: use story ID \\\`\${firstStory.id}\\\`\` : '',
          \`- **Storybook**: \${STORYBOOK_URL}/?path=/story/\${firstStory?.id ?? ''}\`,
        ].filter(Boolean).join('\\n');
      });

      return {
        content: [{
          type: 'text' as const,
          text: \`# Suggestions for "\${description}"\\n\\n\` + blocks.join('\\n\\n'),
        }],
      };
    }
  );

${previewTool}

  const transport = new StdioServerTransport();
  await server.connect(transport);
}

main().catch(() => process.exit(1));
`;
}
function buildPreviewToolCode(ds) {
    return `  // ─── Tool: preview_component ─────────────────────────────────────────────
  server.tool(
    'preview_component',
    \`Render a live preview of a \${METADATA.organizationName} component story directly in the chat via Storybook iframe.\`,
    {
      story_id: z.string().describe(
        'Story ID to preview (get from \`get_component\` or \`search_components\`)'
      ),
    },
    async ({ story_id }) => {
      const component = COMPONENTS.find(c => c.stories.some(s => s.id === story_id));
      const story = component?.stories.find(s => s.id === story_id);

      const iframeUrl = \`\${STORYBOOK_URL}/iframe.html?id=\${encodeURIComponent(story_id)}&viewMode=story\`;
      const fullStoryUrl = \`\${STORYBOOK_URL}/?path=/story/\${story_id}\`;

      const html = \`<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <style>
    *{margin:0;padding:0;box-sizing:border-box}
    body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;background:#f8f9fa;height:100vh;display:flex;flex-direction:column}
    .bar{background:#1a1a2e;color:#fff;padding:8px 16px;display:flex;align-items:center;justify-content:space-between;gap:12px;min-height:40px}
    .bar-left{display:flex;align-items:center;gap:10px;overflow:hidden}
    .org{background:rgba(255,255,255,.15);padding:2px 9px;border-radius:10px;font-size:10px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;white-space:nowrap}
    .comp{font-weight:600;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
    .story{opacity:.55;font-size:12px;white-space:nowrap}
    .link{color:rgba(255,255,255,.65);font-size:11px;text-decoration:none;padding:3px 8px;border:1px solid rgba(255,255,255,.2);border-radius:3px;white-space:nowrap}
    .link:hover{background:rgba(255,255,255,.1)}
    iframe{flex:1;border:none;width:100%;background:#fff}
    .foot{background:#1a1a2e;color:rgba(255,255,255,.3);text-align:center;font-size:9px;padding:5px;text-transform:uppercase;letter-spacing:.1em}
  </style>
</head>
<body>
  <div class="bar">
    <div class="bar-left">
      <span class="org">${ds.organizationName}</span>
      <span class="comp">\${component?.name ?? story_id}</span>
      \${story ? \`<span class="story">/ \${story.name}</span>\` : ''}
    </div>
    <a href="\${fullStoryUrl}" target="_blank" class="link">Open in Storybook ↗</a>
  </div>
  <iframe src="\${iframeUrl}" title="\${component?.name ?? story_id}" sandbox="allow-scripts allow-same-origin" loading="lazy"></iframe>
  <div class="foot">MCP Glue Code Generator · Auto-generated for ${ds.organizationName}</div>
</body>
</html>\`;

      const uiPreview = await createUIResource({
        uri: \`ui://\${METADATA.organizationName.toLowerCase().replace(/\\s+/g, '-')}/\${story_id}-\${Date.now()}\`,
        content: { type: 'rawHtml', htmlString: html },
        encoding: 'text',
      });

      return {
        content: [
          {
            type: 'text' as const,
            text: \`## \${component?.name ?? story_id}\${story ? \` — \${story.name}\` : ''}\\n\` +
              \`Story ID: \\\`\${story_id}\\\`\\n\` +
              \`Full view: \${fullStoryUrl}\`,
          },
          { type: 'resource' as const, resource: uiPreview.resource },
        ],
      };
    }
  );
`;
}
function buildPackageJson(ds) {
    const serverSlug = ds.organizationName.toLowerCase().replace(/\s+/g, '-');
    return JSON.stringify({
        name: `${serverSlug}-design-system-mcp`,
        version: '1.0.0',
        description: `MCP Server for ${ds.organizationName} Design System — auto-generated by MCP Glue Code Generator`,
        type: 'module',
        main: 'build/index.js',
        bin: { [`${serverSlug}-design-mcp`]: 'build/index.js' },
        scripts: {
            build: 'tsc',
            start: 'node build/index.js',
            dev: 'tsx src/index.ts',
        },
        dependencies: {
            '@mcp-ui/server': '^5.16.0',
            '@modelcontextprotocol/sdk': '^1.0.0',
            zod: '^3.23.8',
        },
        devDependencies: {
            '@types/node': '^22.0.0',
            tsx: '^4.19.0',
            typescript: '^5.6.0',
        },
        engines: { node: '>=18.0.0' },
    }, null, 2);
}
function buildReadme(ds) {
    const serverSlug = ds.organizationName.toLowerCase().replace(/\s+/g, '-');
    const topCategories = ds.categories
        .slice(0, 8)
        .map(c => {
        const count = ds.components.filter(comp => comp.category === c).length;
        return `- **${c}** (${count} components)`;
    })
        .join('\n');
    return `# ${ds.organizationName} Design System MCP Server

> Auto-generated by [MCP Glue Code Generator](https://github.com/Maverick7/mcp-glue-code-generator)

MCP server for the **${ds.organizationName} design system**, giving AI assistants direct access to component data, live previews, and code suggestions.

**Source**: ${ds.url}
**Generated**: ${ds.fetchedAt}
**Components**: ${ds.totalComponents} across ${ds.categories.length} categories
**Stories**: ${ds.totalStories} story variants

## Quick Start

\`\`\`bash
npm install
npm run build
\`\`\`

## Integration

### Claude Desktop

Add to \`~/Library/Application Support/Claude/claude_desktop_config.json\`:

\`\`\`json
{
  "mcpServers": {
    "${serverSlug}-design-system": {
      "command": "node",
      "args": ["/absolute/path/to/build/index.js"]
    }
  }
}
\`\`\`

### VS Code (GitHub Copilot)

Add to \`.vscode/mcp.json\` in your project:

\`\`\`json
{
  "servers": {
    "${serverSlug}-design-system": {
      "type": "stdio",
      "command": "node",
      "args": ["/absolute/path/to/build/index.js"]
    }
  }
}
\`\`\`

### Any MCP-Compatible Client

\`\`\`bash
# Run directly
node build/index.js
\`\`\`

## Available Tools

| Tool | Description |
|------|-------------|
| \`list_components\` | Browse all ${ds.totalComponents} components, filter by category |
| \`search_components\` | Full-text search across names, categories, stories, tags |
| \`get_component\` | Get complete details, variants, and story links |
| \`suggest_component\` | AI-powered recommendations for your use case |
| \`preview_component\` | Live iframe preview via Storybook (in supported clients) |

## Component Categories

${topCategories}${ds.categories.length > 8 ? `\n- ...and ${ds.categories.length - 8} more` : ''}

## Example Prompts

Once connected, you can ask:

- *"List all form components"*
- *"Search for button variants"*
- *"Show me the primary button story"*
- *"What component should I use for a dismissable notification?"*
- *"Preview the card component"*

## Refreshing Component Data

To update component data, re-run the generator:

\`\`\`bash
npx mcp-glue-code-generator --storybook ${ds.url} --output .
npm run build
\`\`\`
`;
}
const TSCONFIG_CONTENT = `{
  "compilerOptions": {
    "target": "ES2022",
    "module": "ESNext",
    "moduleResolution": "bundler",
    "esModuleInterop": true,
    "strict": true,
    "outDir": "./build",
    "rootDir": "./src",
    "declaration": true,
    "skipLibCheck": true
  },
  "include": ["src/**/*"]
}
`;
